transition.kernel_code:
pub fn transition(
    actor: &Device,
    s: &OtaState,
    cmd: &Command,
) -> Result<(Option<OtaState>, Reply), Error> {
    match cmd {
        Command::Status => Ok((None, Reply::State(*s))),
        Command::Begin { size } => {
            if !actor.admin {
                return Err(Error::Forbidden);
            }
            if s.active {
                return Err(Error::AlreadyActive);
            }
            if *size == 0 || *size > OTA_SLOT_SIZE {
                return Err(Error::BadSize);
            }
            if s.running_slot > 1 {
                // Includes SLOT_UNKNOWN (0xFF): refuse rather than guess.
                return Err(Error::RunningUnknown);
            }
            let target = 1 - s.running_slot;
            let n = OtaState {
                active: true,
                target_slot: target,
                running_slot: s.running_slot,
                total: *size,
                written: 0,
                error: false,
            };
            Ok((Some(n), Reply::State(n)))
        }
        Command::Write { offset, len, io_ok } => {
            if !actor.admin {
                return Err(Error::Forbidden);
            }
            if !s.active {
                return Err(Error::NoSession);
            }
            if s.error {
                return Err(Error::PriorError);
            }
            if *len == 0 || *len > MAX_CHUNK {
                return Err(Error::ChunkSize);
            }
            let expected = s.written;
            // Idempotent retry: a chunk wholly below the write cursor was
            // already committed; report success without changing state.
            if *offset < expected && *len <= expected - *offset {
                return Ok((None, Reply::State(*s)));
            }
            if *offset != expected {
                return Err(Error::OffsetMismatch);
            }
            // offset == expected == written. Guard the subtraction below so
            // `transition` is total for every state (upstream's
            // `offset + len > total` check rejects this case the same way).
            if *offset > s.total {
                return Err(Error::ExceedsDeclared);
            }
            if *len > s.total - *offset {
                return Err(Error::ExceedsDeclared);
            }
            // Upstream `ota::write`: a failed erase or program poisons the
            // session (error set, cursor not advanced); later writes are
            // refused with PriorError.
            if !*io_ok {
                let n = OtaState {
                    active: s.active,
                    target_slot: s.target_slot,
                    running_slot: s.running_slot,
                    total: s.total,
                    written: s.written,
                    error: true,
                };
                return Ok((Some(n), Reply::State(n)));
            }
            let new_written = *offset + *len;
            let n = OtaState {
                active: s.active,
                target_slot: s.target_slot,
                running_slot: s.running_slot,
                total: s.total,
                written: new_written,
                error: s.error,
            };
            Ok((Some(n), Reply::State(n)))
        }
        Command::End { expected_crc, actual_crc, magic_ok, read_ok, activate_ok } => {
            if !actor.admin {
                return Err(Error::Forbidden);
            }
            if !s.active {
                return Err(Error::NoSession);
            }
            if s.written != s.total {
                return Err(Error::Incomplete);
            }
            // Upstream `ota::end`: any failed check (read-back, magic, CRC,
            // otadata activation) closes the session with the error set;
            // only a fully verified image closes it cleanly.
            // Non-short-circuit `&`: every operand is already computed, and
            // the conjunction extracts without branches.
            let crc_ok = *actual_crc == *expected_crc;
            let verified = *read_ok & *magic_ok & crc_ok & *activate_ok;
            let n = OtaState {
                active: false,
                target_slot: s.target_slot,
                running_slot: s.running_slot,
                total: s.total,
                written: s.written,
                error: !verified,
            };
            Ok((Some(n), Reply::State(n)))
        }
        Command::Abort => {
            if !actor.admin {
                return Err(Error::Forbidden);
            }
            if !s.active {
                return Err(Error::NoSession);
            }
            let n = OtaState {
                active: false,
                target_slot: s.target_slot,
                running_slot: s.running_slot,
                total: s.total,
                written: 0,
                error: false,
            };
            Ok((Some(n), Reply::State(n)))
        }
    }
}

OtaState.kernel_code:
pub struct OtaState {
    pub active: bool,
    /// The slot being written (0 or 1).
    pub target_slot: u8,
    /// The slot the bootloader loaded us from (0 or 1), or `SLOT_UNKNOWN`.
    pub running_slot: u8,
    /// The declared firmware size for this session.
    pub total: u32,
    /// Bytes committed so far.
    pub written: u32,
    pub error: bool,
}

