validate_session.kernel_code:
pub fn validate_session(store: &SessionStore, token: &[u8; 8], now: u32) -> bool {
    slot_valid(&store.s0, token, now)
        || slot_valid(&store.s1, token, now)
        || slot_valid(&store.s2, token, now)
        || slot_valid(&store.s3, token, now)
}

check_auth.kernel_code:
pub fn check_auth(
    cfg: &AuthCfg,
    store: &SessionStore,
    now: u32,
    cookie_present: bool,
    cookie_token: &[u8; 8],
    bearer_present: bool,
    bearer_match: bool,
    akh_present: bool,
    akh_match: bool,
    akq_present: bool,
    akq_match: bool,
    digest_ok: bool,
    is_https: bool,
    is_health: bool,
) -> AuthDecision {
    let blocked = transport_blocks(is_https, cfg.allow_http_tokens);
    // `validate_session` is pure; compute it unconditionally so the extracted
    // code binds it directly (its result is only consulted when a cookie is
    // present, exactly as upstream short-circuits `cookie && validate`).
    let vs = validate_session(store, cookie_token, now);
    // Non-short-circuit `&`: all operands are already evaluated, so this is
    // the same logical AND as `&&` but extracts without an inner branch.
    let valid_cookie = cookie_present & vs;
    let bearer_block = bearer_present & blocked;
    let bearer_ok = bearer_present & cfg.bearer_set & bearer_match;
    let akh_block = akh_present & blocked;
    let akh_ok = akh_present & cfg.apikey_set & akh_match;
    let akq_block = akq_present & blocked;
    let akq_ok = akq_present & cfg.apikey_set & akq_match;
    if cfg.public_access {
        AuthDecision::Allowed
    } else if is_health {
        AuthDecision::Allowed
    } else if valid_cookie {
        AuthDecision::Allowed
    } else if bearer_block {
        AuthDecision::Forbidden
    } else if bearer_ok {
        AuthDecision::Allowed
    } else if akh_block {
        AuthDecision::Forbidden
    } else if akh_ok {
        AuthDecision::Allowed
    } else if akq_block {
        AuthDecision::Forbidden
    } else if akq_ok {
        AuthDecision::Allowed
    } else if digest_ok {
        AuthDecision::AllowedSetSession
    } else {
        AuthDecision::Challenge
    }
}

ct_eq8.kernel_code:
pub fn ct_eq8(a: &[u8; 8], b: &[u8; 8]) -> bool {
    let mut diff: u8 = 0;
    diff |= a[0] ^ b[0];
    diff |= a[1] ^ b[1];
    diff |= a[2] ^ b[2];
    diff |= a[3] ^ b[3];
    diff |= a[4] ^ b[4];
    diff |= a[5] ^ b[5];
    diff |= a[6] ^ b[6];
    diff |= a[7] ^ b[7];
    diff == 0
}

