read_only.kernel_code:
pub fn read_only(cmd: &Command) -> bool {
    match cmd {
        Command::Status => true,
        _ => false,
    }
}

Command.kernel_code:
pub enum Command {
    /// `POST /api/ota/begin/{size}` — open a session for `size` bytes.
    Begin { size: u32 },
    /// `POST /api/ota/write/{offset}` — write a `len`-byte chunk at `offset`.
    /// `io_ok`: whether the flash erase + program of the chunk succeeded
    /// (trusted IO, done only for a chunk the kernel would commit).
    Write { offset: u32, len: u32, io_ok: bool },
    /// `GET /api/ota/end/{expected_crc}` — verify and activate. The trusted
    /// IO results: `read_ok` (the image read back from flash), `magic_ok`
    /// (its first byte), `actual_crc` (its CRC-32), `activate_ok` (otadata
    /// written; done only when the rest verified).
    End { expected_crc: u32, actual_crc: u32, magic_ok: bool, read_ok: bool, activate_ok: bool },
    /// `GET /api/ota/abort`.
    Abort,
    /// `GET /api/ota/status`.
    Status,
}

is_zero8.kernel_code:
pub fn is_zero8(t: &[u8; 8]) -> bool {
    let mut nz: u8 = 0;
    nz |= t[0];
    nz |= t[1];
    nz |= t[2];
    nz |= t[3];
    nz |= t[4];
    nz |= t[5];
    nz |= t[6];
    nz |= t[7];
    nz == 0
}

