def is_zero8 (t : Array Std.U8 8#usize) : Result Bool := do
  let i ← Array.index_usize t 0#usize
  let nz ← lift (0#u8 ||| i)
  let i1 ← Array.index_usize t 1#usize
  let nz1 ← lift (nz ||| i1)
  let i2 ← Array.index_usize t 2#usize
  let nz2 ← lift (nz1 ||| i2)
  let i3 ← Array.index_usize t 3#usize
  let nz3 ← lift (nz2 ||| i3)
  let i4 ← Array.index_usize t 4#usize
  let nz4 ← lift (nz3 ||| i4)
  let i5 ← Array.index_usize t 5#usize
  let nz5 ← lift (nz4 ||| i5)
  let i6 ← Array.index_usize t 6#usize
  let nz6 ← lift (nz5 ||| i6)
  let i7 ← Array.index_usize t 7#usize
  let nz7 ← lift (nz6 ||| i7)
  ok (nz7 = 0#u8)

slot_valid.kernel_code:
pub fn slot_valid(slot: &SessionSlot, token: &[u8; 8], now: u32) -> bool {
    ct_eq8(&slot.token, token) && !is_zero8(&slot.token) && age_ok(now, slot.created)
}

AuthDecision.kernel_code:
pub enum AuthDecision {
    /// Public or an existing credential — serve the request.
    Allowed,
    /// Fresh Digest login — serve and set a session cookie.
    AllowedSetSession,
    /// A token over plaintext HTTP when that is not allowed.
    Forbidden,
    /// No valid credential — answer 401 with a Digest challenge.
    Challenge,
}
